using Sigov.Application.Agro.Permissions; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Application.Agro.Agroindustrias;
public sealed class AgroAgroindustriaValidator{public Result Validar(AgroAgroindustriaCreateRequest r)=>string.IsNullOrWhiteSpace(r.Nome)?Result.Failure("Agroindústria exige nome."):string.IsNullOrWhiteSpace(r.TipoAtividade)?Result.Failure("Agroindústria exige atividade."):Result.Success();}
public sealed class AgroInspecaoMunicipalValidator{public Result Validar(AgroInspecaoMunicipalCreateRequest r)=>r.AgroindustriaId<=0?Result.Failure("Inspeção exige agroindústria."):r.DataInspecao==default?Result.Failure("Inspeção exige data."):(!string.IsNullOrWhiteSpace(r.ExigenciasJson)&&r.ExigenciasJson!="[]"&&r.PrazoAdequacao is null)?Result.Failure("Inspeção com exigências deve ter prazo de adequação."):Result.Success();}
public sealed class AgroAgroindustriaService:IAgroAgroindustriaService{private readonly IAgroAccessChecker _a;private readonly AgroAgroindustriaValidator _v;private readonly IAgroAgroindustriaRepository _r; public AgroAgroindustriaService(IAgroAccessChecker a,AgroAgroindustriaValidator v,IAgroAgroindustriaRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.agroindustrias"),ct); public async Task<Result<PagedResult<AgroAgroindustriaResponse>>> ListarAsync(int page,int pageSize,CancellationToken ct){var c=await C(AgroPermissions.AgroindustriaVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroAgroindustriaResponse>>.Failure(c.Error!); return Result<PagedResult<AgroAgroindustriaResponse>>.Success(await _r.ListarAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,page,pageSize,ct));} public async Task<Result<AgroAgroindustriaResponse>> ObterAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.AgroindustriaVisualizar,ct); if(c.IsFailure)return Result<AgroAgroindustriaResponse>.Failure(c.Error!); var row=await _r.ObterAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,ct); return row is null?Result<AgroAgroindustriaResponse>.Failure("Agroindústria não encontrada."):Result<AgroAgroindustriaResponse>.Success(row);} public async Task<Result<long>> CriarAsync(AgroAgroindustriaCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.AgroindustriaCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.UsuarioId,r,ct));} public async Task<Result> AtualizarAsync(long id,AgroAgroindustriaCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.AgroindustriaEditar,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,r,ct); return Result.Success();} public async Task<Result> ExcluirAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.AgroindustriaExcluir,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.ExcluirAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,ct); return Result.Success();}}
public sealed class AgroInspecaoMunicipalService:IAgroInspecaoMunicipalService{private readonly IAgroAccessChecker _a;private readonly AgroInspecaoMunicipalValidator _v;private readonly IAgroAgroindustriaRepository _r; public AgroInspecaoMunicipalService(IAgroAccessChecker a,AgroInspecaoMunicipalValidator v,IAgroAgroindustriaRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.inspecao_municipal"),ct); public async Task<Result<PagedResult<AgroInspecaoMunicipalResponse>>> ListarAsync(long agroindustriaId,CancellationToken ct){var c=await C(AgroPermissions.InspecaoVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroInspecaoMunicipalResponse>>.Failure(c.Error!); return Result<PagedResult<AgroInspecaoMunicipalResponse>>.Success(await _r.ListarInspecoesAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,agroindustriaId,ct));} public async Task<Result<long>> CriarAsync(long agroindustriaId,AgroInspecaoMunicipalCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.InspecaoCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var req=r with{AgroindustriaId=agroindustriaId}; var v=_v.Validar(req); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarInspecaoAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,agroindustriaId,c.Value.UsuarioId,req,ct));} public async Task<Result> ConcluirAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.InspecaoConcluir,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.ConcluirInspecaoAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,ct); return Result.Success();}}
